import base64, os
os.chdir(r"C:\Users\dsdar\Documents\vietnam-deals")
files = {}
files["scorer.py"] = ""
files["scraper.py"] = ""
files["site_generator.py"] = ""
files["main.py"] = ""
for name, data in files.items():
    with open(name, "wb") as f:
        f.write(base64.b64decode(data))
    print(f"Written: {name}")
print("All files deployed!")

# Syntax check
import py_compile
for name in files:
    try:
        py_compile.compile(name, doraise=True)
        print(f"  Syntax OK: {name}")
    except py_compile.PyCompileError as e:
        print(f"  SYNTAX ERROR: {name}")
        print(f"    {e}")